from pathlib import Path
import re, json, openpyxl
source=Path('/Users/martin/Downloads/FLZR_Website_Rewrite_Comparison_v1.xlsx')
w=openpyxl.load_workbook(source,data_only=True)
s=w['Rewrite Comparison']
rows=[{'row':r,'page':s.cell(r,2).value,'section':s.cell(r,3).value,'text':s.cell(r,5).value} for r in range(2,35)]
page_order=list(dict.fromkeys(r['page'] for r in rows))
routes={'Home':'/en','Agency':'/en/agency','Trainings':'/en/trainings','Promotion':'/en/promotion','Video Consulting':'/en/video-consulting','PoS Management':'/en/pos-management','Sales Force':'/en/sales-force','Go To Markets':'/en/go-to-markets','Business Intelligence':'/en/business-intelligence','References':'/en/cases','Career':'/en/careers'}
cta_targets={'Home':['/en/agency','/en/cases'],'Agency':['/en/contact','/en/careers'],'Trainings':['Training cases within /en/cases; provide a working filtered destination'],'Promotion':['/en/contact'],'Video Consulting':['https://www.saturn.de/de/service/live-beratung'],'PoS Management':['Merchandising cases within /en/cases; provide a working filtered destination'],'Sales Force':['/en/contact'],'Go To Markets':['/en/contact'],'Business Intelligence':['A real sample-dashboard destination is needed; do not replace the label'],'Career':['A verified FLZR application destination is needed','https://www.my-flzr.com/']}
lines=['# FLZR English content — verbatim source plan','','Revised approval draft · 16 September 2026','','This document replaces the previous proposal. The previous rewritten headlines, additional paragraphs, tool descriptions, claims corrections and new CTA labels are withdrawn. No CMS or frontend changes have been made.','','## Source rules','','- General English page copy comes only from **Rewrite Comparison, column E (Rewritten Copy)** in the supplied workbook. Column B supplies the existing page names. Columns D, F and G are not alternative public-copy sources.','- Keep the spreadsheet wording exactly, including spelling, punctuation, numbers, claims and arrow characters. Only block boundaries and visual formatting may change.','- The original FLZR website supplies only **actual case-study records and the Cases/References page**. Retain that source wording; do not use the earlier rewritten CMS case narratives as substitute source text.','- Proof paragraphs already written in the spreadsheet remain the exact spreadsheet text on their respective service pages. A linked case page separately retains its original-website wording. These are separate content blocks, not blended or rewritten paragraphs.','- Editorial recommendations and placeholders inside column E are shown below as **editorial notes**, not published as customer-facing copy. They do not authorize adding text from another source.','- No generated SEO copy, service-card descriptions, additional headings, process text, testimonials or page introductions. No new public section labels unless they are drawn verbatim from the spreadsheet.','- Existing navigation, legal text and global footer are outside this content replacement. Existing design, media and component behavior can be reused; existing marketing paragraphs cannot be carried into the revised pages as filler.','','## Block treatment','','Use the current homepage components and styling as the layout reference, not as an additional copy source. Keep its media treatment, typography, section surfaces and spacing. Do not retain every homepage section if the spreadsheet provides no copy for it.','','| Component | Use |','|---|---|','| `oneSPHeader` | First sentence of Hero & Problem as headline; the remaining sentence as support copy. Preserve every character. |','| `flzrSectionBand` | Visual grouping only. Hide editorial badges/headings that would introduce extra text. |','| `contentSection` | Exact Services & Proof paragraph, or a sentence split where indicated. |','| `flzrTwoThirdsContentSection` | Exact proof paragraph beside existing relevant media; omit an invented headline. Use `contentSection` if the component requires extra heading text. |','| `casesGalleryFiltered` / paginated variant | Original-site case content with original titles and project details. |','| Existing CTA/link components | Exact quoted CTA labels from column E. Quotation marks, the separating slash, and `(kept)` are workbook notation, not button text. |','','Do not shorten the long source sentences to fit the hero. Adjust type size, line breaks and spacing, and stack copy/media as needed on mobile. Do not turn all-caps styling into a stored copy change.','','## Page-by-page content','','Everything in the quoted blocks below is literal spreadsheet copy. Block labels, destinations and layout notes are planning annotations and do not appear as website text.']
verified=[]
for i,page in enumerate(page_order,1):
 lines += ['',f'## {i}. {page}', '',f'Proposed app route: `{routes[page]}`','']
 if page=='References':
  lines += ['**Source exception: original FLZR website only.**','','Original page: [FLZR References](https://flzr.com/references/).','','Do not use spreadsheet E29–E31 for this page, because your latest instruction assigns Cases/References to the original website. Do not use the earlier proposal’s new introduction, headline or CTA.','','**Structure:** original page heading/media → existing original category labels → original case entries → original client section, where present.','','Retain the original client names, project labels, descriptions, result wording, retail partners and project periods. Split each original record into corresponding case-detail blocks without rewriting it. Keep distinct projects for the same client separate. Preserve existing case IDs/URLs when matching records are found.','','The new app currently has three English FLZR case records. Their existing rewritten narratives are not the approved copy source. Reconcile them with the original website, and populate missing cases from the original records only. Additional service-page case material on the original website may be used on the corresponding case detail page, without editorial additions.','','Do not invent detail or results where an original case contains only a short record. This draft specifies the source and structure; the original wording remains available at the linked page for approval.']
  continue
 group=[r for r in rows if r['page']==page]
 hero=group[0]
 parts=hero['text'].split('. ',1)
 assert len(parts)==2
 h=parts[0]+'.'; body=parts[1]
 assert h+' '+body==hero['text']
 lines += [f'**Block 1 — Hero heading · E{hero["row"]}**','','> '+h,'',f'**Block 2 — Hero support · E{hero["row"]}**','','> '+body]
 verified += [{'cell':f'E{hero["row"]}','source':hero['text'],'blocks':[h,body],'join':' '}]
 proof=group[1]
 if page in ['Go To Markets','Career']:
  lines += ['',f'**Editorial note · E{proof["row"]} — not public copy**','','> '+proof['text'],'']
  if page=='Go To Markets':
   lines += ['No case/proof block is proposed for this page until you provide or identify approved original case content. The editorial note itself is not displayed.']
  else:
   lines += ['The workbook does not contain the actual role descriptions or testimonials. Do not import them from the original Career page under the current source restriction. Omit those blocks for now; this page contains the supplied hero/support and CTAs only.']
 else:
  lines += ['',f'**Block 3 — Services & Proof · E{proof["row"]}**','','> '+proof['text']]
  if page=='Home':
   lines += ['','Layout: the two sentences may be separated into adjacent service and case-introduction blocks. Their wording stays exactly as shown. A case gallery can follow using original-site case content. No additional Reach, Team or Careers prose is supplied in these Home rows.']
  elif page=='Agency':
   lines += ['','Layout: the paragraph may be split after its first sentence. Do not add number-strip labels, a new process section, team biographies or careers-teaser copy from another source.']
  else:
   lines += ['','Layout: keep the full proof paragraph as its own block. An accompanying original-source case entry can remain a separate linked case component. Do not replace or edit the spreadsheet proof paragraph.']
  verified += [{'cell':f'E{proof["row"]}','source':proof['text'],'blocks':[proof['text']],'join':''}]
 cta=group[2]; labels=re.findall(r'"([^"]+)"',cta['text'])
 assert labels
 lines += ['',f'**CTA block · E{cta["row"]}**','']
 for label,target in zip(labels,cta_targets[page]):
  lines += ['> '+label,'',f'Destination: {target}','']
 verified += [{'cell':f'E{cta["row"]}','source':cta['text'],'labels':labels}]
 if page=='Business Intelligence':
  lines += ['Keep “See a sample dashboard →” unchanged. If no approved dashboard exists, leave the CTA pending rather than substituting new wording.']
lines += ['','## Layout and implementation scope','','1. Arrange the exact copy above into existing FLZR blocks; use fewer sections where the workbook contains less content.','2. Create the seven missing English service pages; update Home, Agency, Cases/References and Career. Link services to their pages without inventing card descriptions.','3. For Home, use the supplied hero, Services & Proof copy and two CTA labels, with original-source cases as a distinct gallery. Do not fill Reach, Team or Careers sections with legacy or newly written paragraphs.','4. Do not independently rewrite the Services hub, AI Solutions, contact page, navigation labels, metadata, or other languages. Route/link wiring needed to reach the approved pages can change.','5. Stage exact original case content separately, preserving existing IDs and relationships where possible. Reuse already-existing records when they represent the same case.','6. Before publishing, compare all revised public text fields against their source cells or original case record. Only approved formatting and block boundaries may differ.','7. Verify desktop/mobile layout and working links, then present previews for approval.','','## Content not supplied','','| Item | Treatment |','|---|---|','| Career role descriptions and testimonials | Omit; column E contains an editorial recommendation, not those texts. |','| Go To Markets case | Omit; no case text is supplied or identified. |','| Sample dashboard destination | Keep exact BI label pending an actual destination. |','| Additional Home reach/team/careers prose | Omit from the revised composition; no text is supplied in the relevant spreadsheet rows. |','| New service headings, tool explanations, card copy and SEO descriptions | Do not write them. |','','## Approval','','Approve the block arrangement and source separation shown here. This approval draft preserves the spreadsheet wording; it does not apply the previous proposal’s editorial corrections. No content or layout changes have been applied to the app or CMS.','']
p=Path('docs/flzr-english-content-plan.md');p.write_text('\n'.join(lines))
for v in verified:
 if 'blocks' in v:assert v['join'].join(v['blocks'])==s[v['cell']].value
 else:assert v['labels']==re.findall(r'"([^"]+)"',s[v['cell']].value)
assert len(page_order)==11
assert len(verified)==28
Path('tmp/flzr-content-plan/verbatim-verification.json').write_text(json.dumps({'pages':page_order,'verified_source_cells':[v['cell'] for v in verified],'editorial_only':['E24','E33'],'references_excluded':['E29','E30','E31']},indent=2))
print(f'Updated {p}: {len(page_order)} pages, {len(verified)} public-copy source cells verified exactly; 2 editorial-note cells excluded from public copy; References assigned to original website.')
